function spmi_report_value($value) { $value = trim((string) $value); return $value === '' ? '-' : $value; }
function spmi_report_auditor_evidence($value) { $items = json_decode((string) $value, TRUE); if (!is_array($items)) return [(string) $value]; $lines = []; foreach ($items as $item) { if (!is_array($item)) continue; $lines[] = (string) (isset($item['original_name']) ? $item['original_name'] : '-') . ' / ' . (string) (isset($item['mime_type']) ? $item['mime_type'] : '-') . ' / ' . (string) (isset($item['size_bytes']) ? (int) $item['size_bytes'] : 0) . ' bytes / ' . (string) (isset($item['sha256']) ? $item['sha256'] : '-'); } return $lines ?: ['-']; }
?>
