<?php echo html_escape($item->indicator_code_snapshot . ' — ' . $item->indicator_title_snapshot); ?></small></td><td><?php echo nl2br(html_escape($item->realization_snapshot)); ?><hr><small>URL: <?php echo html_escape(spmi_report_value(isset($item->evidence_url_snapshot) ? $item->evidence_url_snapshot : NULL)); ?><br>File: <?php echo html_escape(spmi_report_value(isset($item->evidence_file_original_name_snapshot) ? $item->evidence_file_original_name_snapshot : NULL)); ?><br>MIME: <?php echo html_escape(spmi_report_value(isset($item->evidence_file_mime_type_snapshot) ? $item->evidence_file_mime_type_snapshot : NULL)); ?><br>Ukuran: <?php echo html_escape(spmi_report_value(isset($item->evidence_file_size_bytes_snapshot) ? $item->evidence_file_size_bytes_snapshot : NULL)); ?><br>SHA-256: <?php echo html_escape(spmi_report_value(isset($item->evidence_file_sha256_snapshot) ? $item->evidence_file_sha256_snapshot : NULL)); ?><br>Bukti auditor: <?php foreach (spmi_report_auditor_evidence(isset($item->auditor_evidence_snapshot) ? $item->auditor_evidence_snapshot : NULL) as $line): ?><?php echo nl2br(html_escape($line)); ?><br><?php endforeach; ?></small></td><td><?php echo html_escape($item->score); ?></td><td><?php echo nl2br(html_escape($item->descriptor_snapshot)); ?></td><td><?php echo html_escape(spmi_report_value(isset($item->finding_type_snapshot) ? $item->finding_type_snapshot : NULL)); ?><br><?php echo nl2br(html_escape(spmi_report_value(isset($item->finding_snapshot) ? $item->finding_snapshot : NULL))); ?></td><td><?php echo nl2br(html_escape(spmi_report_value(isset($item->recommendation_snapshot) ? $item->recommendation_snapshot : NULL))); ?></td><td><?php echo nl2br(html_escape(spmi_report_value(isset($item->improvement_plan_snapshot) ? $item->improvement_plan_snapshot : NULL))); ?></td><td><?php echo html_escape(spmi_report_value(isset($item->evidence_date_snapshot) ? $item->evidence_date_snapshot : NULL)); ?></td></tr><?php endforeach; ?></tbody></table></div><